#pragma once

#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <cmath>
#include <cstdint>
#include <string>
#include <optional>

namespace ptv {

// Runtime state for zero-g navigation and comfort.
struct CZeroGState {
    bool active{false};
    bool anchored{false};
    ptv::Vec3 velocity{0.0f, 0.0f, 0.0f};
    ptv::Vec3 ang_velocity_rps{0.0f, 0.0f, 0.0f}; // roll/pitch/yaw or xyz axis rates (rad/s)
    ptv::Vec3 anchor_normal{0.0f, 1.0f, 0.0f};

    // Tunables (filled from params on attach; can be overwritten by live params if present)
    float accel_mps2{1.6f};
    float max_speed_mps{2.2f};
    float lin_damping{1.2f};   // 1/s in exponential decay exp(-d*t)
    float ang_damping{1.8f};   // 1/s
    float vignette_spin_scale{0.6f}; // comfort multiplier

    float vignette_intensity{0.0f}; // 0..1 suggestion for HUD system
};

// --- Small math helpers on engine math types (Vec3/Quat are simple xyz and wxyz) ---
inline ptv::Vec3 v3_add(const ptv::Vec3& a, const ptv::Vec3& b) { return {a.x + b.x, a.y + b.y, a.z + b.z}; }
inline ptv::Vec3 v3_sub(const ptv::Vec3& a, const ptv::Vec3& b) { return {a.x - b.x, a.y - b.y, a.z - b.z}; }
inline ptv::Vec3 v3_mul(const ptv::Vec3& a, float s) { return {a.x * s, a.y * s, a.z * s}; }
inline float    v3_dot(const ptv::Vec3& a, const ptv::Vec3& b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
inline float    v3_len(const ptv::Vec3& a) { return std::sqrt(std::max(0.0f, v3_dot(a,a))); }
inline ptv::Vec3 v3_norm(const ptv::Vec3& a) { float L = v3_len(a); return (L > 1e-6f)? v3_mul(a, 1.0f/L) : ptv::Vec3{0,0,0}; }
inline ptv::Vec3 v3_cross(const ptv::Vec3& a, const ptv::Vec3& b) { return {a.y*b.z - a.z*b.y, a.z*b.x - a.x*b.z, a.x*b.y - a.y*b.x}; }

inline ptv::Quat q_mul(const ptv::Quat& A, const ptv::Quat& B) {
    // (w, x, y, z)
    return ptv::Quat{
        A.w*B.w - A.x*B.x - A.y*B.y - A.z*B.z,
        A.w*B.x + A.x*B.w + A.y*B.z - A.z*B.y,
        A.w*B.y - A.x*B.z + A.y*B.w + A.z*B.x,
        A.w*B.z + A.x*B.y - A.y*B.x + A.z*B.w
    };
}
inline ptv::Quat q_norm(const ptv::Quat& q) {
    float n = std::sqrt(q.w*q.w + q.x*q.x + q.y*q.y + q.z*q.z);
    if (n <= 1e-6f) return ptv::Quat{1,0,0,0};
    float s = 1.0f/n; return ptv::Quat{q.w*s, q.x*s, q.y*s, q.z*s};
}
inline ptv::Quat q_from_axis_angle(const ptv::Vec3& axis, float angle_rad) {
    ptv::Vec3 na = v3_norm(axis);
    float s = std::sin(0.5f*angle_rad);
    return q_norm(ptv::Quat{std::cos(0.5f*angle_rad), na.x*s, na.y*s, na.z*s});
}
inline ptv::Quat q_from_euler_xyz(float rx, float ry, float rz) {
    // intrinsic XYZ (roll X, pitch Y, yaw Z)
    ptv::Quat qx = q_from_axis_angle({1,0,0}, rx);
    ptv::Quat qy = q_from_axis_angle({0,1,0}, ry);
    ptv::Quat qz = q_from_axis_angle({0,0,1}, rz);
    return q_mul(qz, q_mul(qy, qx));
}
inline ptv::Vec3 q_rotate(const ptv::Quat& q, const ptv::Vec3& v) {
    // v' = q * (0,v) * conj(q)
    ptv::Quat p{0, v.x, v.y, v.z};
    ptv::Quat qc{q.w, -q.x, -q.y, -q.z};
    ptv::Quat r = q_mul(q, q_mul(p, qc));
    return {r.x, r.y, r.z};
}
inline ptv::Vec3 basis_forward(const ptv::Quat& q) { return q_rotate(q, {0,0,1}); }
inline ptv::Vec3 basis_right  (const ptv::Quat& q) { return q_rotate(q, {1,0,0}); }
inline ptv::Vec3 basis_up     (const ptv::Quat& q) { return q_rotate(q, {0,1,0}); }

// Rotate current orientation so its up aligns with target normal (minimal rotation)
inline ptv::Quat align_up_to_normal(const ptv::Quat& current, const ptv::Vec3& target_normal) {
    ptv::Vec3 up = basis_up(current);
    ptv::Vec3 n  = v3_norm(target_normal);
    float c = std::clamp(v3_dot(up, n), -1.0f, 1.0f);
    if (c > 0.9995f) return current; // already aligned
    ptv::Vec3 axis = v3_cross(up, n);
    float angle = std::acos(c);
    ptv::Quat dq = q_from_axis_angle(axis, angle);
    return q_norm(q_mul(dq, current));
}

// Exponential damping factor exp(-d * dt)
inline float damp_exp(float d, float dt) { return std::exp(-std::max(0.0f, d) * std::max(0.0f, dt)); }

// Finds and parses this mechanic's live params from CMechanicBinding (if present).
inline std::optional<nlohmann::json> read_live_params(World& w, std::uint32_t e, const char* mech_id) {
    if (!w.has<CMechanicBinding>(e)) return std::nullopt;
    auto& mb = w.get<CMechanicBinding>(e);
    for (const auto& ent : mb.entries) {
        if (ent.id == mech_id || ent.builtin_id == mech_id) {
            try {
                auto j = nlohmann::json::parse(ent.params_json, nullptr, /*allow_exceptions=*/false);
                if (j.is_object()) return j;
            } catch (...) { return std::nullopt; }
        }
    }
    return std::nullopt;
}

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <string>
#include "zero_g_navigation_shared.h"

namespace ptv {

class ZeroGNavigation : public IMechanic {
public:
    void on_attach(World& world, std::uint32_t entity, const nlohmann::json& params) override {
        // Create state with defaults, allow params to override.
        CZeroGState st;
        st.accel_mps2 = params.value("accel_mps2", st.accel_mps2);
        st.max_speed_mps = params.value("max_speed_mps", st.max_speed_mps);
        st.lin_damping = params.value("lin_damping", st.lin_damping);
        st.ang_damping = params.value("ang_damping", st.ang_damping);
        st.vignette_spin_scale = params.value("vignette_spin_scale", st.vignette_spin_scale);

        // Activation: auto-enable when entity has tag "zero_g" or explicit override.
        bool force_active = params.value("force_active", false);
        bool scene_zero_g = false;
        if (world.has<CTag>(entity)) {
            auto& tg = world.get<CTag>(entity);
            for (auto& s : tg.tags) { if (s == "zero_g") { scene_zero_g = true; break; } }
        }
        st.active = (force_active || scene_zero_g);

        world.emplace_or_replace<CZeroGState>(entity, st);
    }

    void on_update(World& world, std::uint32_t entity, float dt) override;

    void on_detach(World& world, std::uint32_t entity) override {
        // Keep state for post-mortem if desired; no-op for now.
    }

    std::string id() const override { return "generated.zero_g_navigation"; }
};

PTV_REGISTER_MECHANIC("generated.zero_g_navigation", ZeroGNavigation)

} // namespace ptv

#include "ptv/api/IMechanic.h"
#include "ptv/ecs/World.h"
#include "ptv/math/Math.h"
#include <nlohmann/json.hpp>
#include <algorithm>
#include <string>
#include <cmath>
#include "zero_g_navigation_shared.h"

namespace ptv {

// Helper to read float2 arrays like [x, y]
static inline void read_vec2(const nlohmann::json& j, const char* key, float& x, float& y, float dx=0.0f, float dy=0.0f) {
    x = dx; y = dy;
    if (j.contains(key) && j.at(key).is_array() && j.at(key).size() >= 2) {
        x = j.at(key)[0].get<float>();
        y = j.at(key)[1].get<float>();
    }
}
static inline ptv::Vec3 read_vec3_def(const nlohmann::json& j, const char* key, const ptv::Vec3& defv) {
    if (j.contains(key) && j.at(key).is_array() && j.at(key).size() >= 3) {
        return ptv::Vec3{ j.at(key)[0].get<float>(), j.at(key)[1].get<float>(), j.at(key)[2].get<float>() };
    }
    return defv;
}

void ZeroGNavigation::on_update(World& world, std::uint32_t entity, float dt) {
    if (!world.valid(entity) || !world.has<CTransform>(entity)) return;
    auto& tr = world.get<CTransform>(entity).t;

    // Ensure state exists.
    if (!world.has<CZeroGState>(entity)) world.emplace_or_replace<CZeroGState>(entity, CZeroGState{});
    auto& st = world.get<CZeroGState>(entity);

    // Pull live params (acceptance harness can drive these every frame).
    auto live = read_live_params(world, entity, "generated.zero_g_navigation");
    nlohmann::json p = nlohmann::json::object();
    if (live.has_value() && live->is_object()) p = *live;

    // Runtime toggles
    bool enable = p.value("enable", st.active);
    st.vignette_spin_scale = p.value("vignette_spin_scale", st.vignette_spin_scale);
    st.accel_mps2   = p.value("accel_mps2", st.accel_mps2);
    st.max_speed_mps= p.value("max_speed_mps", st.max_speed_mps);
    st.lin_damping  = p.value("lin_damping", st.lin_damping);
    st.ang_damping  = p.value("ang_damping", st.ang_damping);

    if (!enable) {
        // Soft settle when disabled
        float k = damp_exp(st.lin_damping, dt);
        st.velocity = v3_mul(st.velocity, k);
        float ka = damp_exp(st.ang_damping, dt);
        st.ang_velocity_rps = v3_mul(st.ang_velocity_rps, ka);
        st.vignette_intensity = 0.0f;
        st.active = false;
        return;
    }
    st.active = true;

    // Read inputs (left/right sticks, frame selection, grip, optional surface normal hint)
    float lx=0.0f, ly=0.0f, rx=0.0f, ry=0.0f; // lx: strafe, ly: forward; rx: yaw/roll, ry: pitch
    read_vec2(p, "left_stick", lx, ly, 0.0f, 0.0f);
    read_vec2(p, "right_stick", rx, ry, 0.0f, 0.0f);
    bool grip_anchor = p.value("grip_anchor", true);
    bool grip_held   = p.value("grip_held", false);
    std::string frame = p.value("control_frame", std::string("hmd")); // "hmd" or "controller"

    // Compute thrust in world space.
    ptv::Vec3 thrust_world{0,0,0};
    if (frame == "controller") {
        // If provided, use controller forward in params, else fall back to HMD forward
        ptv::Vec3 ctrl_fwd = read_vec3_def(p, "controller_forward", basis_forward(tr.rotation));
        ptv::Vec3 ctrl_right = read_vec3_def(p, "controller_right", basis_right(tr.rotation));
        thrust_world = v3_add(v3_mul(ctrl_right, lx), v3_mul(ctrl_fwd, ly));
    } else {
        // Head-relative (HMD = player rig here)
        ptv::Vec3 fwd = basis_forward(tr.rotation);
        ptv::Vec3 right = basis_right(tr.rotation);
        thrust_world = v3_add(v3_mul(right, lx), v3_mul(fwd, ly));
    }
    thrust_world = v3_norm(thrust_world);

    // 6DOF linear dynamics with gentle drift
    if (!st.anchored) {
        st.velocity = v3_add(st.velocity, v3_mul(thrust_world, st.accel_mps2 * dt));
        // Speed clamp
        float speed = v3_len(st.velocity);
        if (speed > st.max_speed_mps) {
            st.velocity = v3_mul(v3_norm(st.velocity), st.max_speed_mps);
        }
        // Damping
        float k = damp_exp(st.lin_damping, dt);
        st.velocity = v3_mul(st.velocity, k);
        // Integrate position
        tr.position = v3_add(tr.position, v3_mul(st.velocity, dt));
    }

    // Angular assist from right stick: map to yaw/pitch/roll rates (rad/s)
    // Convention: rx -> yaw (around up), ry -> pitch (around right). Optional roll via p.value("roll_input", 0.0f)
    float roll_in = p.value("roll_input", 0.0f);
    ptv::Vec3 desired_rps{ roll_in, ry, rx }; // X=roll, Y=pitch, Z=yaw
    // Blend into ang velocity (first-order)
    st.ang_velocity_rps = v3_add( v3_mul(st.ang_velocity_rps, damp_exp(st.ang_damping, dt)), v3_mul(desired_rps, (1.0f - damp_exp(st.ang_damping, dt))) );

    // Integrate orientation
    ptv::Quat dq = q_from_euler_xyz(st.ang_velocity_rps.x * dt, st.ang_velocity_rps.y * dt, st.ang_velocity_rps.z * dt);
    tr.rotation = q_norm(q_mul(dq, tr.rotation));

    // Anchoring
    if (grip_anchor) {
        if (grip_held && !st.anchored) {
            st.anchored = true;
            st.velocity = {0,0,0};
            st.ang_velocity_rps = {0,0,0};
            // Use hint normal if provided, else current up (keeps pose stable)
            st.anchor_normal = read_vec3_def(p, "surface_normal", basis_up(tr.rotation));
        } else if (!grip_held && st.anchored) {
            st.anchored = false;
        }

        if (st.anchored) {
            // Align to surface normal smoothly
            ptv::Quat target = align_up_to_normal(tr.rotation, st.anchor_normal);
            // Slerp-lite via nlerp for stability
            const float a = std::clamp(p.value("anchor_align_rate", 6.0f) * dt, 0.0f, 1.0f);
            // nlerp(q, target, a)
            ptv::Quat q{ tr.rotation.w*(1.0f-a) + target.w*a,
                         tr.rotation.x*(1.0f-a) + target.x*a,
                         tr.rotation.y*(1.0f-a) + target.y*a,
                         tr.rotation.z*(1.0f-a) + target.z*a };
            tr.rotation = q_norm(q);
        }
    }

    // Comfort vignette based on angular speed
    float omega = v3_len(st.ang_velocity_rps); // rad/s
    // Map: 0 rad/s -> 0, 3 rad/s -> ~1 (tunable)
    float vign = std::clamp(st.vignette_spin_scale * (omega / 3.0f), 0.0f, 1.0f);
    st.vignette_intensity = vign;
}

} // namespace ptv
